const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Etosha Pan bounding box (approximate)
  var etoshaPan = ee.Geometry.Polygon([
    [15.5, -18.8],
    [16.5, -18.8],
    [16.5, -19.2],
    [15.5, -19.2]
  ]);

  // Time periods
  var janPeriod = ee.DateRange('2020-01-10', '2020-01-20');
  var augPeriod = ee.DateRange('2020-08-20', '2020-08-30');

  // 2. Data Acquisition
  // Function to get cloud-masked Sentinel-2 images
  function getS2Collection(dateRange, geometry) {
    var collection = ee.ImageCollection('COPERNICUS/S2_SR')
      .filterBounds(geometry)
      .filterDate(dateRange.start(), dateRange.end());

    // Cloud masking using QA60 band
    function maskClouds(image) {
      var qa = image.select('QA60');
      var cloudBitMask = 1 << 10;
      var cirrusBitMask = 1 << 11;
      var mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                  .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
      return image.updateMask(mask);
    }

    return collection.map(maskClouds);
  }

  // Get collections for both periods
  var janCollection = getS2Collection(janPeriod, etoshaPan);
  var augCollection = getS2Collection(augPeriod, etoshaPan);

  // Check collection sizes
  var janSize = janCollection.size().getInfo();
  var augSize = augCollection.size().getInfo();

  console.log('Jan 2020 Images:', janSize);
  console.log('Aug 2020 Images:', augSize);

  // If either collection is empty, try fallback or output C1
  if (janSize === 0 || augSize === 0) {
    console.log('Missing data in one or both periods.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Processing - Calculate water extent for each period
  // Function to calculate water extent from a collection
  function calculateWaterExtent(collection, geometry, periodName) {
    // Create median composite
    var composite = collection.median();

    // Calculate MNDWI (Modified Normalized Difference Water Index)
    // MNDWI = (Green - SWIR) / (Green + SWIR)
    var mndwi = composite.normalizedDifference(['B3', 'B11']).rename('MNDWI');

    // Water mask (MNDWI > 0 indicates water)
    var waterMask = mndwi.gt(0);

    // Count water pixels
    var waterCount = waterMask.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: 3000,  // Using 3km scale to avoid timeout
      maxPixels: 1e9
    }).get('MNDWI');

    // Get total valid pixels
    var validPixels = waterMask.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: 3000,
      maxPixels: 1e9
    }).get('MNDWI');

    return {
      waterCount: waterCount.getInfo(),
      validPixels: validPixels.getInfo(),
      mndwi: mndwi,
      waterMask: waterMask
    };
  }

  // Calculate for January
  var janResult = calculateWaterExtent(janCollection, etoshaPan, 'January');
  var augResult = calculateWaterExtent(augCollection, etoshaPan, 'August');

  console.log('Jan 2020 Water Pixels:', janResult.waterCount);
  console.log('Jan 2020 Valid Pixels:', janResult.validPixels);
  console.log('Aug 2020 Water Pixels:', augResult.waterCount);
  console.log('Aug 2020 Valid Pixels:', augResult.validPixels);

  // Check for no valid pixels (C2)
  if (janResult.validPixels === 0 || augResult.validPixels === 0) {
    console.log('No valid pixels after processing.');
    console.log('<answer>C2</answer>');
    return;
  }

  // Check for calculation failures (C3)
  if (janResult.waterCount === null || augResult.waterCount === null ||
      isNaN(janResult.waterCount) || isNaN(augResult.waterCount)) {
    console.log('Calculation failed.');
    console.log('<answer>C3</answer>');
    return;
  }

  // 4. Compare and output answer
  var waterDecrease = augResult.waterCount < janResult.waterCount;

  console.log('Water extent change: Jan =', janResult.waterCount.toFixed(0), 
              'Aug =', augResult.waterCount.toFixed(0));
  console.log('Decrease?', waterDecrease);

  if (waterDecrease) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
